using System;
using UnityEngine;

namespace RyanAssets.GameFeel {
    /// <summary>
    /// Maps every <see cref="SfxCue"/> to its sound. The kit's library is generated by
    /// Ryan &gt; Game Feel &gt; Rebuild (which only fills cues that have no clips yet, so hand-tuned
    /// entries survive a rebuild) and referenced from <see cref="GameFeelSettings"/>.
    /// </summary>
    [CreateAssetMenu(menuName = "Ryan/Game Feel/Sfx Cue Library", fileName = "SfxCueLibrary")]
    public sealed class SfxCueLibrary : ScriptableObject {
        [Serializable]
        public sealed class Entry {
            public SfxCue cue;
            public SfxSound sound = new();
        }

        [SerializeField] Entry[] entries = Array.Empty<Entry>();

        [NonSerialized] SfxSound[] byCue;

        public Entry[] Entries {
            get => entries;
            set { entries = value ?? Array.Empty<Entry>(); byCue = null; }
        }

        /// <summary>The sound for <paramref name="cue"/>, or null when the library has none.</summary>
        public SfxSound Get(SfxCue cue) {
            if (byCue == null)
                Index();
            int i = (int)cue;
            return i >= 0 && i < byCue.Length ? byCue[i] : null;
        }

        void Index() {
            int max = 0;
            foreach (SfxCue cue in Enum.GetValues(typeof(SfxCue)))
                max = Mathf.Max(max, (int)cue);
            byCue = new SfxSound[max + 1];
            foreach (Entry entry in entries) {
                if (entry == null || (int)entry.cue < 0 || (int)entry.cue > max)
                    continue;
                if (byCue[(int)entry.cue] != null)
                    Debug.LogWarning($"{name}: cue {entry.cue} is listed twice; the first entry is used.", this);
                else
                    byCue[(int)entry.cue] = entry.sound;
            }
        }

        void OnValidate() => byCue = null;
    }
}
